(window.FREALLY_I18N = window.FREALLY_I18N || {})["hi"] = {"hero.headline":"<span class=\"hl-muted\">हर दौर की वोकल चेन।</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">एक प्लगइन।</span>","hero.cycle":"एक प्लगइन।|आपकी आवाज़ पर।|हर DAW में।","hero.sub":"कोई कलाकार खोजें, एक दौर चुनें, प्ले दबाएँ। Takelight पूरी वोकल चेन लोड करता है — ट्यूनिंग, EQ, कंप्रेशन, डी-एसिंग, डिले, रिवर्ब और वोकल बस — जो उसके अपने मॉड्यूल से बनी है। ऑफ़लाइन और 100% AI-मुक्त।","price.note":"अभी कुछ भी बिक्री के लिए नहीं है। संस्करण 1.0 से Freally Takelight एक बार के लाइसेंस के रूप में बिकेगा, उससे पहले पूरे प्लगइन का मुफ़्त ट्रायल।","hero.chipStandalone":"स्टैंडअलोन","what.title":"यह क्या है","what.p1":"कच्ची वोकल रिकॉर्ड जैसी नहीं लगती, और यह फ़र्क़ एक चेन का है: ट्यूनिंग, EQ, कंप्रेसर, डी-एसर, सेंड पर डिले और रिवर्ब, और एक वोकल बस, सही क्रम में, सही सेटिंग्स पर।","what.p2":"Takelight हर कलाकार और हर दौर के लिए एक पूरी चेन एक ही प्लगइन में रखता है, जो उसके अपने मॉड्यूल से बनी है, ताकि उसे सुनने के लिए आपको कभी किसी और प्लगइन की ज़रूरत न पड़े।","what.p3":"एक चेन लोड करें और वह बिना क्लिक के क्रॉसफ़ेड होकर आ जाती है। उसे चार मैक्रो से आकार दें, या रैक खोलें और कोई भी नॉब घुमाएँ।","features.title":"इसमें क्या है","featuresPage.cards.chains.title":"कलाकार और दौर के हिसाब से चेन","featuresPage.cards.chains.body":"किसी कलाकार का नाम लिखें, एक दौर और एक भूमिका चुनें — लीड या ऐड-लिब — और पूरी चेन क्रम से लोड हो जाती है: इंसर्ट, इफ़ेक्ट रिटर्न और वोकल बस।","featuresPage.cards.swap.title":"बिना क्लिक के बदलाव","featuresPage.cards.swap.body":"ट्रैक चलते-चलते चेन बदलें। नई चेन ऑडियो से अलग तैयार होती है और 30 मिलीसेकंड के क्रॉसफ़ेड में आती है, इसलिए कुछ भी चटकता नहीं।","featuresPage.cards.joint.title":"Joint","featuresPage.cards.joint.body":"एक ही रैक में पूरी चेन: पिच करेक्शन, तीन तरह के EQ, पाँच तरह के कंप्रेसर, डी-एसर, गेट, सैचुरेशन, एक्साइटर, लो-फ़ाई, लिमिटर, डबलर, डिले, रिवर्ब, चार रिटर्न और एक वोकल बस।","featuresPage.cards.modes.title":"सरल और उन्नत","featuresPage.cards.modes.body":"सरल चार मैक्रो दिखाता है — ट्यून, टोन, स्पेस और मात्रा। उन्नत हर मॉड्यूल को रेंडर किए गए हार्डवेयर के रूप में दिखाता है, और हर कार्ड वह बनाकर दिखाता है जो उसका मॉड्यूल करता है — आपकी वोकल पर EQ कर्व, कंप्रेसर का कर्व और वह कितना दबाता है — और हर नॉब ऑटोमेट किया जा सकता है।","featuresPage.cards.daw.title":"हर DAW में","featuresPage.cards.daw.body":"Windows, macOS और Linux पर CLAP और VST3, macOS पर AU, और एक स्टैंडअलोन ऐप। आपके प्रोजेक्ट के साथ सेव होता है, लेटेंसी बताता है ताकि आपका DAW सब कुछ मिला सके, और एक साथ कई इंस्टेंस में भरोसेमंद है।","featuresPage.cards.offline.title":"ऑफ़लाइन, निजी, बिना AI","featuresPage.cards.offline.body":"न खाता, न टेलीमेट्री, न मॉडल। प्लगइन और ऐप कभी ऑनलाइन नहीं जाते; अपडेट जाँच और लाइसेंस सक्रियण एक अलग सहायक में चलते हैं, सिर्फ़ तब जब आप कहें।","ladder.title":"1.0 की ओर रास्ता","ladder.intro":"हर संस्करण के लिए एक पंक्ति। यह वही सीढ़ी है जिसका निजी योजना भी पालन करती है — अगर एक हिलती है, तो दूसरी भी हिलती है, और एक बिल्ड गेट दोनों की तुलना करता है।","ladder.rung.v0.1.0":"नींव: प्लगइन CLAP, VST3 और AU के रूप में और स्टैंडअलोन ऐप के रूप में लोड होता है, आपके ऑडियो को बिना छेड़े गुज़ार देता है, अपने लाइसेंस की स्वीकृति माँगता है, और हर क्वालिटी गेट चलता है।","ladder.rung.v0.2.0":"Joint: पूरी वोकल चेन के लिए एक रैक, रेंडर किए गए हार्डवेयर पर पहले EQ, डायनामिक्स और कलर मॉड्यूल, और रिकॉर्डिंग लैंप।","ladder.rung.v0.3.0":"स्पेस: डिले, रिवर्ब, डबलिंग, चौड़ाई और चार इफ़ेक्ट रिटर्न, आपके प्रोजेक्ट की टेम्पो के साथ।","ladder.rung.v0.4.0":"ट्यून: क्लासिक सिग्नल प्रोसेसिंग से पिच करेक्शन, आपकी वोकल से पहचाना गया स्केल, और रिकॉर्डिंग के लिए लो-लेटेंसी मोड।","ladder.rung.v0.5.0":"पहली रोशनी: कोई कलाकार और दौर खोजें, और पूरी चेन एक क्लिक में लोड हो जाती है। पहला पूरा संस्करण।","ladder.rung.v0.5.5":"Input Check, ऐड-लिब चेन, आपके अपने प्रीसेट और पूर्ववत करना।","ladder.rung.v0.5.6":"विज़ुअल कार्ड: हर मॉड्यूल दिखाता है कि वह क्या करता है — आपकी वोकल के लाइव स्पेक्ट्रम पर EQ कर्व, और कंप्रेसर कर्व के साथ यह कि वह कितना दबाता है — सिर्फ़ नॉब नहीं।","ladder.rung.v0.6.0":"कलाकार चेन की पहली खेप, हर जॉनर के लिए एक चेन, और सूची का पेज।","ladder.rung.v0.7.0":"हर DAW में: आपके प्रोजेक्ट के साथ सेव, ऑटोमेट करने योग्य, लेटेंसी बताता है, और एक साथ कई इंस्टेंस में भरोसेमंद।","ladder.rung.v0.8.0":"पूरी ताक़त से स्टैंडअलोन ऐप, और macOS व Linux पर Takelight।","ladder.rung.v0.9.0":"कलाकार चेन की दूसरी खेप, और यथार्थता व परफ़ॉर्मेंस का एक दौर।","ladder.rung.v0.9.5":"Reference Match: एक रेफ़रेंस लोड करें, और Takelight उसकी वोकल के डिले, रिवर्ब, टोन और बाक़ी सब पढ़ता है, और उन्हें अपने ही मॉड्यूल पर सुझाता है।","ladder.rung.v1.0.0-beta":"मज़बूत: तीन सिस्टमों के लिए इंस्टॉलर, अपडेट जाँच, ट्रायल और लाइसेंस, और पूरा मैनुअल। इस साइट पर अब भी कोई डाउनलोड नहीं।","ladder.rung.v1.0.0-rc":"रिलीज़ कैंडिडेट: हर फ़ाइल की समीक्षा और हर होस्ट की हाथ से जाँच।","ladder.rung.v1.0.0":"रिलीज़: मुफ़्त ट्रायल, एक बार का लाइसेंस, और इस साइट के अब तक के पहले डाउनलोड।","ladder.rung.v1.1.0":"Vocal Match: आपकी वोकल का टोन, आपके अपने रेफ़रेंस के सामने सेट।","ladder.rung.v1.2.0":"डबल्स और हार्मनी, आपके लिए परत दर परत।","ladder.rung.v1.3.0":"कलाकार चेन की तीसरी खेप, और प्रोड्यूसरों की भेजी चेन।","ladder.rung.v1.4.0":"Freally MIDI Master और Freally Unloop तक पुल।","ladder.rung.v1.5.0":"प्लगइन के रूप में Pro Tools (AAX), अगर Avid की शर्तें इजाज़त दें।","ladder.note":"जो संस्करण पूरा हो चुका है वह बना और टैग किया गया है। यह डाउनलोड नहीं है: अभी कोई नहीं है, और 1.0.0 तक कोई नहीं होगा।","honest.title":"वे बातें जिन्हें ज़्यादातर साइटें सबसे नीचे रखती हैं","honest.voice.title":"चेन आवाज़ नहीं है","honest.voice.body":"एक चेन प्रोसेसिंग दोहराती है: ट्यूनिंग, EQ, कंप्रेशन, डिले और रिवर्ब। आपकी आवाज़, आपका माइक, आपका कमरा और आपकी अदायगी आपकी ही रहती है, और कोई प्रीसेट किसी को किसी और जैसा नहीं सुनाता।","honest.start.title":"एक चेन शुरुआत भर है","honest.start.body":"एक चेन वह जगह है जहाँ से आपकी आवाज़ शुरू होती है, किसी साउंड का वादा नहीं। मैक्रो घुमाएँ, रैक खोलें और उसे अपना बनाएँ; आप जो भी बदलते हैं, वह कभी लॉक नहीं होता।","honest.downloads.title":"1.0.0 से पहले कोई डाउनलोड नहीं है","honest.downloads.body":"इस पेज पर न बीटा, न प्रीव्यू बिल्ड, न अर्ली एक्सेस। संस्करण 1.0 पूरे प्लगइन के मुफ़्त ट्रायल और एक बार के लाइसेंस के साथ आता है।","honest.network.title":"यह कभी ऑनलाइन नहीं जाता","honest.network.body":"प्लगइन और स्टैंडअलोन ऐप में कोई नेटवर्क कोड नहीं है, और अगर जुड़ा तो बिल्ड गेट फ़ेल हो जाता है। अपडेट जाँच और लाइसेंस सक्रियण एक अलग सहायक में रहेंगे जो सिर्फ़ आपके कहने पर काम करता है।","site.tagline":"हर दौर की वोकल चेन। एक प्लगइन।","footer.licence":"मालिकाना — सर्वाधिकार सुरक्षित। © Mike Weaver। ओपन सोर्स नहीं। संपर्क: freallyproducts@gmail.com।","footer.yours":"Freally Takelight से आप जो ऑडियो, प्रीसेट और प्रोजेक्ट बनाते हैं, वे आपके हैं।","footer.disclaimer":"कलाकारों के नाम सिर्फ़ एक शैली की पहचान करते हैं। Freally Takelight किसी भी कलाकार, प्रोड्यूसर, इंजीनियर, लेबल, प्रकाशन या प्लगइन निर्माता से जुड़ा नहीं है, न ही उनके द्वारा समर्थित या स्वीकृत है। एक चेन प्रोसेसिंग लागू करती है, आवाज़ नहीं।","featuresPage.lead":"एक वोकल प्लगइन, जिसमें हर कलाकार और हर दौर के लिए पूरी वोकल चेन है — ट्यूनिंग, EQ, कंप्रेशन, डी-एसिंग, डिले, रिवर्ब और वोकल बस — जो उसके अपने मॉड्यूल से बनी है।","featuresPage.version":"यह पेज Freally Takelight संस्करण 1.0 बताता है: इस पर जो कुछ है वह 1.0 में है, और 1.0 के बाद की योजना वाली कोई चीज़ इस पर नहीं है।","featuresPage.numbers.plugin":"प्लगइन पूरी चेन के लिए, कोई और प्लगइन ख़रीदने की ज़रूरत नहीं","featuresPage.numbers.macros":"मैक्रो: ट्यून, टोन, स्पेस और मात्रा","featuresPage.numbers.returns":"इफ़ेक्ट रिटर्न, साथ में एक वोकल बस","featuresPage.numbers.plugins":"प्लगइन फ़ॉर्मैट, साथ में एक स्टैंडअलोन ऐप","featuresPage.numbers.systems":"ऑपरेटिंग सिस्टम: Windows, macOS और Linux","featuresPage.numbers.languages":"भाषाएँ","featuresPage.numbers.ai":"AI मॉडल","featuresPage.numbers.borrowed":"इम्पल्स रिस्पॉन्स, सैंपल या कॉपी किए प्रीसेट","featuresPage.free.title":"अभी ख़रीदने को कुछ नहीं","featuresPage.free.body":"संस्करण 1.0 से पहले न कुछ बिक्री के लिए है, न डाउनलोड के लिए। उसके बाद पूरे प्लगइन का मुफ़्त ट्रायल और एक कीमत, एक बार चुकाई गई: न सब्सक्रिप्शन, न खाता। इससे आप जो ऑडियो बनाते हैं, वह आपका है।","featuresPage.cards.title":"संस्करण 1.0 क्या करता है","featuresPage.cards.tune.title":"ट्यून और Auto Key","featuresPage.cards.tune.body":"क्लासिक सिग्नल प्रोसेसिंग से पिच करेक्शन, जिसमें स्केल आपकी वोकल या साइडचेन से पहचाना जाता है, और उसके ज़रिए रिकॉर्ड करने के लिए लो-लेटेंसी मोड।","featuresPage.cards.inputCheck.title":"Input Check और A/B","featuresPage.cards.inputCheck.body":"Input Check आपके टेक के दस सेकंड सुनता है और इनपुट नॉब सेट करता है, साथ ही आपकी चेन में मौजूद गेट, हाई-पास और डी-एसर भी। A/B चेन की तुलना आपकी लोड की गई रेफ़रेंस फ़ाइल से, बराबर लाउडनेस पर, या चेन के ही दूसरे संस्करण से करता है; रेफ़रेंस कभी सेव नहीं होता।","featuresPage.cards.lightDark.title":"लाइट और डार्क","featuresPage.cards.lightDark.body":"एक डार्क और एक लाइट मोड, दोनों Freally ग्रीन में, हर नॉब, फ़ेडर और स्विच हर मोड के लिए Blender में रेंडर किया गया, और रिकॉर्डिंग लैंप जो चेन चालू होने पर जलता है।","featuresPage.compare.title":"व्यावसायिक औज़ारों के साथ आमने-सामने","featuresPage.compare.intro":"Freally Takelight 1.0, उन वोकल प्लगइनों के बगल में जिन्हें प्रोड्यूसर किसी नाम वाली साउंड के लिए उठाते हैं। दूसरे उत्पाद का हर सेल उसके निर्माता के पेजों या प्रकाशित कवरेज से है, अक्टूबर 2026 में जाँचा गया; जो सेल उनसे तय नहीं होता, उस पर 'सत्यापित नहीं' लिखा है।","featuresPage.compare.feature":"फ़ीचर","featuresPage.compare.row.price":"क़ीमत (USD, अक्टूबर 2026)","featuresPage.compare.ourPrice":"मुफ़्त ट्रायल के बाद एक कीमत, एक बार","featuresPage.compare.note.muzePrice":"आजीवन, या हर 4 हफ़्ते $24","featuresPage.compare.legend.unknown":"सत्यापित नहीं","featuresPage.compare.row.artists":"कलाकारों के नाम पर चेन","featuresPage.compare.legend.yes":"उपलब्ध","featuresPage.compare.note.artistEra":"कलाकार, दौर और भूमिका के अनुसार","featuresPage.compare.note.muzePresets":"52 कलाकार प्रीसेट","featuresPage.compare.legend.no":"उपलब्ध नहीं","featuresPage.compare.note.engineerChain":"एक इंजीनियर की चेन","featuresPage.compare.note.producerChain":"एक प्रोड्यूसर की चेन","featuresPage.compare.row.modes":"सरल और उन्नत मोड","featuresPage.compare.row.key":"आपकी वोकल से स्केल पहचानता है","featuresPage.compare.row.formats":"CLAP, VST3 और AU","featuresPage.compare.legend.partly":"आंशिक","featuresPage.compare.row.systems":"Windows, macOS और Linux","featuresPage.compare.row.noAi":"कोई AI या मशीन लर्निंग नहीं","featuresPage.compare.summaryTitle":"संक्षेप में","featuresPage.compare.summary":"सिर्फ़ Takelight में कलाकार, दौर और भूमिका के हिसाब से चेन, तीनों प्लगइन फ़ॉर्मैट, Windows और macOS के साथ Linux, और बिल्कुल भी AI नहीं है।","featuresPage.compare.theyWinTitle":"वे कहाँ आगे हैं","featuresPage.compare.theyWin":"Muze के पास आज 52 कलाकार प्रीसेट हैं और यह Pro Tools में चलता है; Takelight की पहली कलाकार चेन संस्करण 0.5.0 के साथ आईं, और 1.0 में यह Pro Tools प्लगइन नहीं है। CLA Vocals और The Spirit उन्हीं इंजीनियर और प्रोड्यूसर के साथ बनाए गए जिनके नाम पर वे हैं।","featuresPage.compare.asOf":"Takelight का कॉलम संस्करण 1.0 है, जो अभी आया नहीं है। दूसरे उत्पाद भी बदलते हैं; यह तालिका अक्टूबर 2026 की है। उत्पादों के नाम उनके मालिकों के हैं और यहाँ सिर्फ़ तुलना के लिए इस्तेमाल हुए हैं।","featuresPage.why.title":"यह ऐसे क्यों बना है","featuresPage.why.built.title":"बनाया गया, उधार नहीं लिया","featuresPage.why.built.body":"हर मॉड्यूल Takelight की अपनी क्लासिक सिग्नल प्रोसेसिंग है। न इम्पल्स रिस्पॉन्स, न सैंपल, न उधार का कोड, और किसी दूसरे उत्पाद के प्रीसेट से कॉपी की गई कोई सेटिंग नहीं।","featuresPage.why.names.title":"ईमानदार नाम","featuresPage.why.names.body":"एक चेन का नाम कलाकार और दौर के नाम पर है, और कुछ नहीं। न कोई छवि, न कोई कवर, और किसी को किसी और जैसा सुनाने का कोई वादा नहीं।","featuresPage.why.reference.title":"आपका रेफ़रेंस, बराबर लेवल पर","featuresPage.why.reference.body":"A/B आपकी लोड की हुई रेफ़रेंस फ़ाइल को आपकी आवाज़ के बगल में उसी लाउडनेस पर रखता है, ताकि तेज़ वर्ज़न आपके कानों को कभी धोखा न दे। रेफ़रेंस मेमोरी में ही रहता है और कभी सेव नहीं होता।","featuresPage.why.local.title":"यह आपकी मशीन पर ही रहता है","featuresPage.why.local.body":"न टेलीमेट्री, न क्लाउड। आपकी वोकल कभी आपके कंप्यूटर से बाहर नहीं जाती, और अगर प्लगइन या ऐप में कभी नेटवर्क कोड जुड़ा, तो बिल्ड गेट फ़ेल हो जाता है।","featuresPage.why.roster.title":"परिवार के लिए एक सूची","featuresPage.why.roster.body":"कलाकार और जॉनर अपने नाम Freally MIDI Master और Freally Unloop के साथ साझा करते हैं, इसलिए एक ही सूची पूरी Freally लाइन में चलती है।","featuresPage.coming.title":"अभी क्या आना बाक़ी है","featuresPage.coming.intro":"साफ़-साफ़ कहें, क्योंकि जो फ़ीचर सूची अपनी कमियाँ छिपाए, वह पढ़ने लायक नहीं। यह पेज संस्करण 1.0 बताता है, और Takelight एक-एक पायदान बनाया जा रहा है: उस पर सब कुछ अभी बना नहीं है। 1.0 की राह का हर पायदान अपनी स्थिति के साथ चिह्नित है।","featuresPage.limits.title":"1.0 क्या नहीं करता","featuresPage.limits.voice":"यह नहीं बदलता कि कौन गा रहा है, और कभी किसी आवाज़ की नकल नहीं करता।","featuresPage.limits.roster":"इसमें हर कलाकार नहीं है। सूची हर संस्करण के साथ बढ़ती है।","featuresPage.limits.match":"यह आपकी वोकल को किसी रेफ़रेंस से अपने आप नहीं मिलाता; Vocal Match की योजना 1.0 के बाद की है।","featuresPage.limits.aax":"1.0 में यह Pro Tools प्लगइन (AAX) नहीं है।","featuresPage.coming.downloads":"संस्करण 1.0 से पहले कोई डाउनलोड नहीं है, और इस पन्ने पर भी कोई नहीं।","docs.intro":"यह मैनुअल हर संस्करण के साथ बढ़ता है। अभी यह चेन ढूँढने, आपके प्रीसेट, सरल मोड और उसके चार नॉब, A/B, रैक और हर कार्ड क्या दिखाता है, पूर्ववत करने, उसके चार इफ़ेक्ट रिटर्न, ट्यून, Input Check और उसके पच्चीस मॉड्यूल के बारे में है।","docs.start.title":"शुरुआत करना","docs.browser.title":"चेन ढूँढना","docs.presets.title":"आपके प्रीसेट","docs.simple.title":"सरल मोड और चार नॉब","docs.ab.title":"A/B","docs.rack.title":"रैक","docs.cards.title":"हर कार्ड क्या दिखाता है","docs.undo.title":"पूर्ववत करें और फिर से करें","docs.returns.title":"रिटर्न और थ्रो","docs.tune.title":"ट्यून और Auto Key","docs.inputCheck.title":"Input Check","docs.automation.title":"ऑटोमेशन","docs.lamp.title":"रिकॉर्डिंग लैंप और मीटर","docs.modules.title":"मॉड्यूल","docs.project.title":"आपके प्रोजेक्ट के साथ सेव","docs.agreement.title":"लाइसेंस अनुबंध","docs.settings.title":"सेटिंग्स","docs.language.title":"भाषाएँ","docs.disclaimer.title":"अस्वीकरण","docs.privacy.title":"निजता और नेटवर्क","docs.report.title":"जब कुछ गड़बड़ हो जाए","docs.start.p1":"Takelight आपके DAW में CLAP, VST3 या AU प्लगइन के रूप में, या अपने आप में स्टैंडअलोन ऐप के रूप में चलता है। इसे किसी वोकल ट्रैक पर लगाएँ। यह सरल मोड में खुलता है: कोई कलाकार या शैली खोजें, एक दौर और एक भूमिका चुनें, और पूरी चेन लोड हो जाती है। जब तक आप कोई चेन लोड नहीं करते या कोई मॉड्यूल नहीं जोड़ते, आपकी ऑडियो बिना बदले गुज़रती है।","docs.start.p2":"संस्करण 1.0.0 से पहले कोई डाउनलोड नहीं है, और कोड निजी है।","docs.browser.p1":"ऊपर की खोज में लिखें — कोई कलाकार, उपनाम या शैली — या कहीं से भी Ctrl+K (Mac पर Cmd+K) दबाएँ। लिखते-लिखते चेन दिखने लगती हैं: हर कलाकार अपने दौरों के साथ, हर दौर अपने वर्षों और अपनी भूमिकाओं के साथ, जैसे लीड, ऐड-लिब या FX। एक चुनें और पूरी चेन क्रम से, बिना क्लिक के, ट्रैक चलते-चलते लोड हो जाती है। ऐरो कुंजियाँ सूची में ऊपर-नीचे ले जाती हैं, Enter लोड करता है, और Escape उसे बंद करता है।","docs.browser.p2":"खोज ख़ाली हो, तो यह वे चेन सुझाती है जो आपने आख़िरी बार लोड की थीं। जिस कलाकार की अभी कोई चेन नहीं है, उसके लिए यह उसकी शैली की चेन सुझाती है, और जो नाम यह नहीं पहचानती, उसके लिए यह साफ़ बताती है और एक शैली सुझाती है।","docs.browser.p3":"संस्करण 0.5.6 में Drake तीन दौरों में है — So Far Gone (2009), Take Care (2011) और आधुनिक दौर (2016–2026) — साथ में Take Care दौर की एक FX चेन, और अठारह शैली चेन: ट्रैप (2000 और 2010 के दशक), शिकागो ड्रिल, इमो रैप, क्लासिक R&B, आधुनिक पॉप, रॉक, कंट्री पॉप और रेगेटन के लिए एक लीड और एक ऐड-लिब। हर चेन का नाम उसके कलाकार या शैली और उसके दौर पर है, और कुछ नहीं।","docs.presets.p1":"ऊपर का 'प्रीसेट सहेजें…' चेन को वैसे ही रखता है जैसे आपने उसे गढ़ा है — हर मॉड्यूल, नॉब, सेंड और फ़ेडर, और सरल के चार नॉब — आपके चुने नाम से। हर प्रीसेट दस्तावेज़ › Freally Takelight › Presets में एक फ़ाइल है, ताकि आप उसका बैकअप ले सकें या उसे किसी को भेज सकें।","docs.presets.p2":"'मेरे प्रीसेट…' उनकी सूची दिखाता है, हर एक के साथ वह चेन जिससे वह बना था, ताकि आप उसे लोड करें, उसका नाम बदलें, उसे एक्सपोर्ट करें या मिटाएँ। 'इंपोर्ट करें…' किसी का भेजा प्रीसेट ले आता है, और अगर उस नाम का प्रीसेट आपके पास पहले से है तो उसके नाम में एक संख्या जोड़ देता है। जो फ़ाइल Takelight प्रीसेट नहीं है, 256 KB से बड़ी है या किसी नए संस्करण से सहेजी गई थी, वह अस्वीकार कर दी जाती है, और सूची कारण बताती है।","docs.presets.p3":"आपके प्रीसेट खोज में भी हैं, 'मेरे प्रीसेट' के नीचे। जिस चेन से कोई प्रीसेट बना था, वह बाद के किसी संस्करण में अपडेट हो, तो प्रीसेट अपडेट हुई चेन पर लोड होता है, आपका हर बदलाव बनाए रखता है, और यह बताता है।","docs.simple.p1":"सरल में रिकॉर्डिंग लैंप, चेन का नाम, चार बड़े नॉब और इन व आउट मीटर दिखते हैं; ऊपर के स्विच से खुलने वाला उन्नत पूरा रैक दिखाता है। आपका प्रोजेक्ट याद रखता है कि आपने उसे किस दृश्य में छोड़ा था, और सेटिंग्स में आप चुनते हैं कि नया इंस्टेंस किसमें खुले।","docs.simple.p2":"ट्यून तय करता है कि वोकल कितनी तेज़ी से और कितने स्वाभाविक ढंग से ट्यून हो। टोन चेन को 1 kHz के आसपास गहरा या चमकीला बनाता है, और डी-एसर उसके साथ चलता है। स्पेस हर इफ़ेक्ट सेंड को एक साथ 12 dB तक ऊपर या नीचे करता है। मात्रा आपकी ड्राई वोकल के मुक़ाबले पूरी चेन का हिस्सा तय करती है, 0 % पर ड्राई से लेकर 100 % पर पूरी चेन तक।","docs.simple.p3":"ट्यून, टोन और स्पेस बीच में हों और मात्रा 100 % पर, तो चेन वैसे ही बजती है जैसे वह बनाई गई थी, और हर चेन इसी तरह लोड होती है। हर नॉब एक होस्ट पैरामीटर है, इसलिए आपका DAW उसे ऑटोमेट कर सकता है, और डबल-क्लिक उसे डिफ़ॉल्ट पर लौटा देता है।","docs.ab.p1":"'रेफ़रेंस लोड करें…' आपके सिस्टम का फ़ाइल डायलॉग खोलता है, या कोई फ़ाइल विंडो पर छोड़ें। यह WAV, AIFF, FLAC और MP3 पढ़ता है, 20 मिनट तक, और पट्टी फ़ाइल का नाम, उसकी लंबाई और उसकी लाउडनेस दिखाती है। B रेफ़रेंस को वहीं से चलाता है जहाँ आपका DAW है (स्टैंडअलोन ऐप में शुरुआत से), A आपकी चेन है, और हर स्विच 20 मिलीसेकंड का क्रॉसफ़ेड है।","docs.ab.p2":"'लाउडनेस मिलाएँ' रेफ़रेंस को आपकी वोकल की लाउडनेस पर चलाता है, ताकि आप लेवल नहीं, टोन परखें। रेफ़रेंस सिर्फ़ मेमोरी में रहता है: वह कभी आपके प्रोजेक्ट, किसी प्रीसेट या कहीं और सेव नहीं होता, और नेटवर्क ड्राइव पर रखी फ़ाइल अस्वीकार कर दी जाती है।","docs.ab.p3":"'चेन की तुलना करें' आपकी चेन के दो संस्करण रखता है। A वह है जिसे आप संपादित कर रहे हैं; B दबाएँ और वह एक कॉपी के रूप में शुरू होता है, इसलिए कुछ नहीं बदलता; उसे संपादित करें, और A और B दोनों अपना-अपना रखते हैं। दोनों आपके प्रोजेक्ट के साथ सेव होते हैं।","docs.rack.p1":"रैक पूरी चेन को सिग्नल के क्रम में, चार पंक्तियों में रखता है: फ़्रंट एंड (स्लॉट F1 और F2), इंसर्ट (I1 से I12), चार इफ़ेक्ट रिटर्न (A से D, स्लॉट R1 से R12) और बस (B1 से B4)।","docs.rack.p2":"किसी ख़ाली स्लॉट के मेन्यू से मॉड्यूल चुनें और वह जुड़ जाएगा। उसका कार्ड उसका हर कंट्रोल दिखाता है: मानों के लिए नॉब, स्विच, और विकल्पों के लिए मेन्यू। उसके हेडर में उसका कैरेक्टर (जब एक से ज़्यादा हों), बायपास (B), सोलो (S) और उसे हटाने वाला × होता है।","docs.rack.p3":"हर बदलाव बिना क्लिक के होता है। आप जो मॉड्यूल जोड़ते या हटाते हैं वह फ़ेड होकर आता या जाता है, नया कैरेक्टर क्रॉसफ़ेड होता है, और हर नॉब धीरे से सरकता है, इसलिए आप ट्रैक चलते-चलते काम कर सकते हैं। बायपास किया गया मॉड्यूल अपनी लेटेंसी बनाए रखता है, इसलिए आपका DAW समय पर रहता है।","docs.rack.p4":"हर कंट्रोल कीबोर्ड से चलता है। Tab उनके बीच ले जाता है; ऐरो कुंजियाँ नॉब घुमाती हैं, और Shift उसे बड़े कदमों में घुमाता है; Home और End उसे किसी भी सिरे तक ले जाते हैं; डबल-क्लिक उसे डिफ़ॉल्ट पर लौटा देता है।","docs.rack.p5":"एक रैक में उतने ही नॉब आ सकते हैं जितने Takelight एक साथ हिला सकता है — हर स्लॉट सबसे बड़े मॉड्यूल से भरा हो, तो उससे ज़्यादा होंगे — इसलिए उससे आगे कोई मॉड्यूल अस्वीकार हो जाता है और रैक बताता है कि वह भरा हुआ है।","docs.cards.p1":"अपने नॉब के साथ-साथ, हर मॉड्यूल का कार्ड वह बनाकर दिखाता है जो मॉड्यूल करता है, उसी गणित से निकाला गया जो साउंड बनाता है। EQ — पैरामेट्रिक, कंसोल और प्रोग्राम — अपना कर्व आपकी वोकल के ऊपर बनाते हैं जब वह बज रही हो: EQ से पहले उसका स्पेक्ट्रम, धुँधला, और उसके बाद, चमकीला, और पीक एक पल के लिए थमे रहते हैं। हर बैंड का कर्व पर एक बिंदु है: बैंड की फ़्रीक्वेंसी और गेन को एक साथ हिलाने के लिए उसे ड्रैग करें, उसकी चौड़ाई के लिए उसके ऊपर माउस व्हील घुमाएँ, बैंड को वापस लाने के लिए उस पर डबल-क्लिक करें, या ऐरो कुंजियाँ इस्तेमाल करें। पूरा एक ड्रैग पूर्ववत करने में एक ही क़दम है। डी-एसर वह बैंड दिखाता है जिसे वह सुनता है और वह कट जो वह लगाता है, और ट्रिम अपना हाई-पास।","docs.cards.p2":"कंप्रेसर, लेवल राइडर और लिमिटर अपना कर्व बनाते हैं — इनपुट लेवल बनाम आउटपुट लेवल — उस जगह एक बिंदु के साथ जहाँ इस समय आपकी वोकल उस पर है, और उसके नीचे पिछले चार सेकंड का गेन रिडक्शन। एक स्थिर नोट बिंदु को कर्व पर रखता है; एक तीखा अटैक उसे एक पल के लिए ऊपर उठा सकता है, इससे पहले कि कंप्रेसर उसे पकड़ ले। थ्रेशोल्ड को कर्व के साथ ड्रैग करें, या ऐरो कुंजियाँ इस्तेमाल करें: यह उसे सेट करने वाला नॉब घुमाता है। गेट का कार्ड वह लेवल दिखाता है जो उसे सुनाई देता है, उसके थ्रेशोल्ड के सापेक्ष, और जहाँ वह बंद है वहाँ छायांकित।","docs.cards.p3":"डिले अपने रिपीट आपके प्रोजेक्ट की बीट और बार के सापेक्ष एक टाइमलाइन पर बनाता है, हर एक उतना ही ऊँचा जितना फ़ीडबैक और फ़िल्टर उसे छोड़ते हैं; पिंग-पोंग में बाएँ रिपीट रेखा के ऊपर और दाएँ नीचे रहते हैं। रिवर्ब अपना डिके बनाता है — प्री-डिले, शुरुआती रिफ़्लेक्शन और टेल — और रिवर्स गेट अपना स्वेल। डबलर, कोरस और चौड़ाई स्टीरियो फ़ील्ड को ऊपर से दिखाते हैं, और सैचुरेशन, एक्साइटर और लो-फ़ाई अपना कर्व और वे हार्मोनिक्स दिखाते हैं जो वह आपकी वोकल में अभी जोड़ता है।","docs.cards.p4":"सिर्फ़ स्क्रीन पर मौजूद कार्ड ही बनाते हैं, और एक साथ आठ तक EQ कार्ड आपकी वोकल का स्पेक्ट्रम दिखाते हैं। ट्यून के पास इसकी जगह उसका पिच ग्राफ़ है, और पिच शिफ़्टर के पास सिर्फ़ उसके नॉब।","docs.undo.p1":"ऊपर के तीर साउंड में किए गए हर बदलाव को पूर्ववत करते हैं और फिर से करते हैं, 100 क़दम तक: एक नॉब (पूरा एक ड्रैग एक क़दम है), जोड़ा या हटाया गया मॉड्यूल, उसका कैरेक्टर, बायपास और सोलो, सेंड और फ़ेडर, सरल के चार नॉब, इनपुट नॉब, लोड की गई चेन या प्रीसेट, और Input Check का 'लागू करें'। Ctrl+Z पूर्ववत करता है, और Ctrl+Shift+Z या Ctrl+Y फिर से करता है (Mac पर ⌘Z और ⌘⇧Z), जब तक Takelight की विंडो पर फ़ोकस हो, ताकि आपका DAW अपने शॉर्टकट रखे।","docs.undo.p2":"दृश्य, थीम, भाषा और A/B रेफ़रेंस कभी पूर्ववत नहीं होते, और न ही आपके DAW का ऑटोमेशन। हर प्रोजेक्ट खुलते समय नए इतिहास से शुरू होता है, और तुलना का हर पक्ष भी, जब आप उस पर जाते हैं।","docs.returns.p1":"चारों रिटर्न, A से D, में से हर एक को इंसर्ट पंक्ति के अंत से उसके सेंड नॉब के ज़रिए फ़ीड मिलता है, बंद से +6 dB तक। वोकल रिटर्न के तीन स्लॉट से गुज़रती है — मान लीजिए, एक डिले और एक रिवर्ब — और रिटर्न का फ़ेडर तय करता है कि उसका कितना हिस्सा बस में जाते हुए ड्राई वोकल से मिलता है।","docs.returns.p2":"किसी रिटर्न की थ्रो कुंजी दबाए रखें और वोकल उसमें थ्रो हो जाती है: उसका सेंड 0 dB तक उठता है, और छोड़ने पर वापस गिर जाता है, दोनों ओर 5 मिलीसेकंड में। थ्रो A से D होस्ट पैरामीटर भी हैं, इसलिए आपका DAW कोई थ्रो रिकॉर्ड करके उसे वापस चला सकता है — किसी एक शब्द पर डिले की टेल।","docs.returns.p3":"नोट वैल्यू पर सेट किया गया डिले आपके प्रोजेक्ट के टेम्पो के साथ ताल में रहता है, और गाने के दौरान टेम्पो बदलने पर उसके साथ चलता है।","docs.tune.p1":"ट्यून गाए गए हर सुर को उसके स्केल के सबसे नज़दीकी सुर पर खींच लाता है। रीट्यून स्पीड तय करती है कि कितनी तेज़ी से: 0 ms पर आवाज़ एक सुर से दूसरे पर कूदती है, वही सख़्त, सीढ़ीदार साउंड; धीमे पर वह फिसलकर वहाँ पहुँचती है, और कुछ सौ मिलीसेकंड पर ट्यूनिंग मुश्किल से सुनाई देती है। ह्यूमनाइज़ लंबे सुरों को धीरे टिकने देता है, और फ़्लेक्स उन स्कूप और वाइब्रेटो को बचाए रखता है जो सुर से सबसे दूर भटकते हैं। आवाज़ के फ़ॉर्मेंट अपनी जगह रहते हैं, इसलिए उसका चरित्र बना रहता है, और साँसें व व्यंजन बिना छुए गुज़र जाते हैं।","docs.tune.p2":"स्केल मेन्यू Auto Key से शुरू होता है: ट्यून आपकी वोकल सुनता है और लगभग चार सेकंड के गायन में उसका स्केल तय कर लेता है; तब तक वह सबसे नज़दीकी सेमिटोन पर ट्यून करता है और रिकॉर्डिंग लैंप एम्बर जलता है। कार्ड बताता है कि उसे कौन-सा स्केल सुनाई दे रहा है, और लॉक करें उसे थामे रखता है। या ख़ुद क्रोमैटिक या 24 में से कोई भी स्केल चुनें। अगर 20 सेकंड के गायन के बाद भी कोई स्केल सुनाई न दे, तो कार्ड आपसे एक चुनने को कहता है।","docs.tune.p3":"पिच ग्राफ़ आख़िरी चार सेकंड दिखाता है: आपकी गाई पिच एक पतली रेखा के रूप में और ट्यून जो पिच आगे भेजता है वह हरी रेखा के रूप में, उस सुर की रेखा के ऊपर जिसकी ओर वह खींच रहा है।","docs.tune.p4":"किसी सुर को ट्यून करने से पहले सुनने के लिए ट्यून 21 मिलीसेकंड रुकता है, और Takelight यह आपके DAW को बताता है, ताकि वोकल बीट के साथ समय पर रहे। रिकॉर्डिंग के दौरान यह इंतज़ार आपके हेडफ़ोन में होता, इसलिए Auto पर रखा Tracking होस्ट पैरामीटर, जब भी आपका DAW रिकॉर्ड करता है, ट्यून को 4 मिलीसेकंड पर ले आता है, और कार्ड यह बताता है। ख़ुद चुनने के लिए Tracking को On या Off पर रखें।","docs.tune.p5":"एक रैक में एक ही ट्यून होता है, क्योंकि एक ट्यून पूरी वोकल को ट्यून करता है।","docs.tune.p6":"Auto Key इसके बजाय बीट से भी स्केल ढूँढ सकता है। अपने DAW में बीट को Takelight के साइडचेन इनपुट पर भेजें और ट्यून के कार्ड पर 'किसे सुनता है' को 'साइडचेन' पर सेट करें: ट्यून बीट के कॉर्ड के साथ चलता है। आपका प्रोजेक्ट यह चुनाव याद रखता है, और सेटिंग्स नए प्रोजेक्ट के लिए इसे तय करती हैं। जब तक साइडचेन पर कुछ नहीं बजता, ट्यून आपकी वोकल सुनता है, और कार्ड यह बताता है।","docs.inputCheck.p1":"रैक के ऊपर का Input Check रिकॉर्ड करने से पहले आपकी तैयारी करता है। उसे दबाएँ और टेक को दस सेकंड तक गाएँ या बजाएँ; जब तक वह सुनता है, रिकॉर्डिंग लैंप एम्बर जलता है। उसे कम से कम दो सेकंड की आवाज़ चाहिए, और बहुत कम सुनाई देने पर वह फिर से माँगता है।","docs.inputCheck.p2":"फिर वह दिखाता है कि उसे क्या सुनाई दिया — पीक, लेवल, लाउडनेस, नॉइज़ फ़्लोर, 80 Hz से नीचे का रंबल, सिबिलेंस और प्लोसिव — और वह क्या सुझाता है: इनपुट नॉब, ताकि आपकी आवाज़ एक सेहतमंद लेवल पर आए, और गेट थ्रेशोल्ड, हाई-पास और डी-एसर थ्रेशोल्ड। वह सिर्फ़ वही मॉड्यूल सेट करता है जो आपकी चेन में पहले से हैं; जो मॉड्यूल उसमें नहीं है, उस पर 'इस चेन में नहीं' लिखा आता है, और आपके लिए कुछ भी जोड़ा नहीं जाता।","docs.inputCheck.p3":"जब तक आप 'लागू करें' नहीं दबाते, कुछ नहीं बदलता, और 'पूर्ववत करें' पूरे 'लागू करें' को एक ही क़दम में वापस ले लेता है। 'छोड़ें' सब कुछ वैसा ही छोड़ देता है जैसा वह था। अगर टेक क्लिप होता है, तो वह आपसे अपने इंटरफ़ेस का गेन कम करने को कहता है, क्योंकि रिकॉर्डिंग के बाद क्लिपिंग पूर्ववत नहीं की जा सकती।","docs.automation.p1":"हर स्लॉट के पास 24 होस्ट पैरामीटर होते हैं, जिनके नाम स्लॉट पर रखे गए हैं (F1 से B4), और किसी मॉड्यूल के नॉब और स्विच उन्हें क्रम से लेते हैं, ताकि आपका DAW उन्हें ऑटोमेट कर सके। मॉड्यूल जोड़ने, बदलने या हटाने पर पैरामीटर की सूची कभी नहीं बदलती।","docs.automation.p2":"कुछ सेटिंग्स ऑटोमेट नहीं होतीं, क्योंकि किसी नोट के बीच में उन्हें बदलने से क्लिक आएगा: किसी EQ बैंड का टाइप और स्लोप, किसी फ़िल्टर का स्लोप, और डी-एसर के डिटेक्शन जैसे मोड। फिर भी वे आपके प्रोजेक्ट के साथ सेव होती हैं।","docs.lamp.p1":"रैक के ऊपर का रिकॉर्डिंग लैंप तब हरा जलता है जब रैक में कोई मॉड्यूल हो और आपकी आवाज़ आ रही हो, इनपुट क्लिप होने पर लाल झपकता है, और बाकी समय बुझा रहता है। यह एम्बर हो जाता है जब ट्यून का Auto Key स्केल पहचानने के लिए सुन रहा हो, और जब Input Check सुन रहा हो।","docs.lamp.p2":"दोनों ओर के इन और आउट मीटर बाएँ और दाएँ चैनल दिखाते हैं, और इन मीटर के पास इनपुट नॉब आने वाला लेवल सेट करता है, −24 से +24 dB तक; आपका DAW इसे ऑटोमेट कर सकता है। हर मीटर में एक क्लिप लाइट है जो तब तक जली रहती है जब तक आप उस पर क्लिक न करें। कंप्रेसर का कार्ड दिखाता है कि वह वोकल को कितना दबा रहा है, जब तक वह दबा रहा हो।","docs.modules.p1":"संस्करण 0.5.6 में पच्चीस मॉड्यूल हैं। हर एक Takelight का अपना डिज़ाइन है, और कोई भी किसी और उत्पाद होने का दावा नहीं करता।","docs.modules.tune.title":"ट्यून","docs.modules.tune.p1":"किसी स्केल पर पिच करेक्शन — Auto Key, क्रोमैटिक या 24 में से कोई एक — 0 से 400 ms तक की रीट्यून स्पीड, ह्यूमनाइज़ और फ़्लेक्स, और गाई व ट्यून की गई पिच के ग्राफ़ के साथ। हर रैक में एक; ऊपर ट्यून और Auto Key देखें।","docs.modules.trim.title":"ट्रिम","docs.modules.trim.p1":"गेन, पोलैरिटी और चुनने योग्य स्लोप वाला हाई-पास फ़िल्टर: ज़्यादातर चेन में सबसे पहली चीज़।","docs.modules.parametric.title":"पैरामेट्रिक EQ","docs.modules.parametric.p1":"आठ बैंड, हर एक बेल, शेल्फ़, कट या नॉच, कट 6 से 96 dB प्रति ऑक्टेव तक। इसके नॉब एक बार में एक बैंड दिखाते हैं — बैंड उसके नंबर से चुनें — और हर बैंड का कर्व पर अपना बिंदु है।","docs.modules.console.title":"कंसोल EQ","docs.modules.console.p1":"मिक्सिंग कंसोल का चैनल EQ: हाई-पास और लो-पास फ़िल्टर और चार बैंड, चार कैरेक्टर में — ब्रिटिश E, ब्रिटिश G, क्लास A और प्रोपोर्शनल Q।","docs.modules.program.title":"प्रोग्राम EQ","docs.modules.program.p1":"लो और हाई सिरों पर चौड़े, कोमल बूस्ट और कट, और गर्माहट के लिए एक ट्यूब स्टेज।","docs.modules.opto.title":"ऑप्टो कंप्रेसर","docs.modules.opto.p1":"परफ़ॉर्मेंस के साथ चलने वाली चिकनी लेवलिंग, एक पीक रिडक्शन नॉब से, ऑप्टो और ट्यूब ऑप्टो कैरेक्टर में, कंप्रेस या लिमिट करते हुए।","docs.modules.fet.title":"FET कंप्रेसर","docs.modules.fet.p1":"तेज़ और आगे की ओर, फ़िक्स्ड रेशियो और आक्रामक कंप्रेशन के लिए 'सभी' सेटिंग के साथ, और पैरेलल कंप्रेशन के लिए मिक्स कंट्रोल के साथ।","docs.modules.vca.title":"VCA कंप्रेसर","docs.modules.vca.p1":"साफ़ और सटीक, बस और चैनल कैरेक्टर में, RMS या पीक डिटेक्शन, साइडचेन हाई-पास और मिक्स कंट्रोल के साथ।","docs.modules.varimu.title":"वेरी-म्यू कंप्रेसर","docs.modules.varimu.p1":"एक ट्यूब कंप्रेसर जो जितना ज़्यादा काम करता है, उसका रेशियो उतना बढ़ता है, इसलिए वह नरमी से शुरू होता है और मज़बूती से थामे रहता है, छह टाइम कॉन्स्टेंट के साथ; 5 और 6 जितनी देर तक कंप्रेस किया गया हो, उतनी ही धीमी गति से छोड़ते हैं।","docs.modules.punch.title":"पंच कंप्रेसर","docs.modules.punch.p1":"पाँच कैरेक्टर वाला एक कैरेक्टर कंप्रेसर, नॉर्मल से डिस्टॉर्शन 3 तक, चरम कंप्रेशन के लिए न्यूक और एक मिक्स कंट्रोल के साथ।","docs.modules.vox.title":"वॉक्स लेवलर","docs.modules.vox.p1":"सिर्फ़ एक थ्रेशोल्ड और एक आउटपुट से वोकल का लेवल बराबर करता है।","docs.modules.rider.title":"लेवल राइडर","docs.modules.rider.p1":"वोकल के लेवल को एक लक्ष्य लाउडनेस की ओर ले जाता है — धीमे शब्दों के लिए ऊपर, तेज़ शब्दों के लिए नीचे — आपकी तय की गई रेंज और स्पीड के भीतर, और फ़्रेज़ के बीच की साँसों को नहीं छेड़ता। वैकल्पिक 10 ms का लुक-अहेड इसे किसी शब्द से ठीक पहले हिलने देता है; यह 10 ms की लेटेंसी जोड़ता है, जिसे Takelight आपके DAW को बताता है।","docs.modules.deesser.title":"डी-एसर","docs.modules.deesser.p1":"तीखी \"स\" ध्वनियों को काबू करता है, स्प्लिट बैंड या वाइडबैंड, बेल या शेल्फ़ के साथ, और सापेक्ष या निरपेक्ष डिटेक्शन के साथ।","docs.modules.gate.title":"गेट","docs.modules.gate.p1":"फ़्रेज़ के बीच एक गेट या एक्सपैंडर, होल्ड, हिस्टेरिसिस और साइडचेन फ़िल्टर के साथ, ताकि साँसें और ब्लीड उसे न खोलें।","docs.modules.saturation.title":"सैचुरेशन","docs.modules.saturation.p1":"टेप, ट्यूब, ट्रांसफ़ॉर्मर और इन्फ़्लेट, ओवरसैंपल किए हुए ताकि यह जो हार्मोनिक्स जोड़ता है वे साफ़ रहें।","docs.modules.exciter.title":"एक्साइटर","docs.modules.exciter.p1":"आपकी चुनी हुई फ़्रीक्वेंसी के ऊपर हार्मोनिक्स जोड़ता है — विषम, सम या दोनों का मिश्रण — प्रेज़ेंस और एयर के लिए। सिर्फ़ हार्मोनिक्स जोड़े जाते हैं; वोकल ख़ुद बिना छुए गुज़रती है।","docs.modules.lofi.title":"लो-फ़ाई","docs.modules.lofi.p1":"कम बिट्स और कम सैंपल रेट, 24 बिट्स से घटकर 4 तक और 48 kHz से घटकर 1 kHz तक, डिदर, एक एंटी-एलियास फ़िल्टर, ड्राइव और एक मिक्स कंट्रोल के साथ।","docs.modules.limiter.title":"लिमिटर","docs.modules.limiter.p1":"एक ट्रू-पीक लिमिटर: आउटपुट कभी अपनी सीलिंग से ऊपर नहीं जाता, सैंपल के बीच भी नहीं।","docs.modules.delay.title":"डिले","docs.modules.delay.p1":"पाँच कैरेक्टर — डिजिटल, टेप, एनालॉग, पिंग-पोंग और स्लैप। इसका टाइम मिलीसेकंड में या 1/64 से दो बार्स तक के नोट वैल्यू के रूप में सेट होता है, जिनमें ट्रिपलेट और डॉटेड नोट भी हैं, आपके प्रोजेक्ट के साथ ताल में। फ़ीडबैक में फ़िल्टर, वोकल के नीचे डकिंग, और चौड़ाई; 100 % फ़ीडबैक से ऊपर रिपीट बेकाबू होने के बजाय उभरते हैं और टिके रहते हैं।","docs.modules.reverb.title":"रिवर्ब","docs.modules.reverb.p1":"पाँच कैरेक्टर — प्लेट, रूम, हॉल, चैंबर और एम्बिएंस — प्री-डिले, 0.1 से 20 सेकंड तक के डिके, साइज़, डैम्पिंग, डिफ़्यूज़न, मॉड्यूलेशन और रिटर्न पर फ़िल्टर के साथ। डिके वह समय है जो टेल को 60 dB गिरने में लगता है।","docs.modules.reversegate.title":"रिवर्स गेट","docs.modules.reversegate.p1":"रिवर्स रिवर्ब: हर ध्वनि के बाद, एक लहर जो गेट की लंबाई भर उभरती है, 50 ms से एक सेकंड तक, और एकदम रुक जाती है। यह कभी आगे नहीं देखता, इसलिए कोई लेटेंसी नहीं जोड़ता और रिकॉर्ड करते समय भी काम करता है।","docs.modules.doubler.title":"डबलर","docs.modules.doubler.p1":"एक टेक को दो, तीन या चार आवाज़ों में बदलता है, हर एक थोड़ी देर से, टाइम और पिच में थोड़ा भटकती हुई, और स्टीरियो फ़ील्ड में फैली हुई, टाइट और वाइड कैरेक्टर में। मोनो में जोड़ने पर यह वोकल के अपने लेवल के क़रीब रहता है।","docs.modules.chorus.title":"कोरस","docs.modules.chorus.p1":"दो आवाज़ों वाला कोरस, जिसमें एक आवाज़ की पिच ऊपर जाती है जबकि दूसरी की नीचे, रेट, डेप्थ, मिक्स और ड्राइव के साथ; 50 % मिक्स पर यह लेवल बनाए रखता है और मोनो में साफ़ जुड़ता है।","docs.modules.width.title":"चौड़ाई","docs.modules.width.p1":"स्टीरियो इमेज को संकरा या चौड़ा करता है, 0 % पर मोनो से 200 % तक, मोनो योग बदले बिना, और मोनो वोकल को फैलाने के लिए दाईं ओर 30 ms तक का Haas डिले देता है।","docs.modules.shifter.title":"पिच शिफ़्टर","docs.modules.shifter.p1":"आवाज़ को दो ऑक्टेव तक ऊपर या नीचे ले जाता है, उसके फ़ॉर्मेंट अलग से एक ऑक्टेव तक, मिक्स कंट्रोल के साथ: एक ऑक्टेव नीचे का ऐड-लिब। ट्यून की तरह यह 21 मिलीसेकंड रुकता है, या Tracking में 4।","docs.project.p1":"आपका प्रोजेक्ट चेन, हर मॉड्यूल और नॉब, दृश्य, सरल के चार नॉब, तुलना के दोनों पक्ष और यह कि ट्यून किसे सुनता है, सब रखता है। अगर किसी प्रोजेक्ट की सेटिंग्स पढ़ी न जा सकें, तो वह डिफ़ॉल्ट चेन पर खुलता है और मुख्य हिस्से के ऊपर एक बार यह बताता है, जब तक आप उसे हटा न दें।","docs.agreement.p1":"पहली बार खुलने पर Takelight अपना लाइसेंस अनुबंध और अस्वीकरण दिखाता है। जब तक आप सहमत नहीं होते, यह आपकी ऑडियो को बिना बदले गुज़रने देने के अलावा कुछ नहीं करता, इसलिए अस्वीकार करने से कोई ट्रैक कभी चुप नहीं होता।","docs.agreement.p2":"आपका जवाब आपके कंप्यूटर पर रखा जाता है और Takelight की हर खुली कॉपी द्वारा साझा किया जाता है, हर DAW में और स्टैंडअलोन ऐप में भी। आप अनुबंध को कभी भी दोबारा पढ़कर स्वीकार कर सकते हैं।","docs.settings.p1":"सेटिंग्स में आप दूसरी चीज़ों के साथ लाइट या डार्क और भाषा चुनते हैं। आपके चुनाव प्रोजेक्ट के नहीं, कंप्यूटर के होते हैं: वे उस पर Takelight की हर कॉपी पर लागू होते हैं।","docs.language.p1":"Takelight और यह साइट अठारह भाषाएँ बोलते हैं, अरबी दाएँ से बाएँ। कलाकारों के नाम कभी अनुवादित नहीं होते।","docs.disclaimer.p1":"कलाकारों के नाम एक शैली की पहचान करते हैं, और कुछ नहीं। Freally Takelight किसी भी कलाकार, प्रोड्यूसर, इंजीनियर, लेबल, प्रकाशन या प्लगइन निर्माता से जुड़ा नहीं है, न ही उनके द्वारा समर्थित, प्रायोजित या स्वीकृत है। सभी नाम और ट्रेडमार्क उनके मालिकों के हैं, और किसी कलाकार की छवि, लोगो, हस्ताक्षर या कलाकृति कहीं भी इस्तेमाल नहीं होती।","docs.disclaimer.p2":"एक चेन प्रोसेसिंग लागू करती है; वह यह नहीं बदलती कि कौन गा रहा है, और कोई भी चेन किसी ख़ास साउंड का वादा नहीं करती। Takelight के मॉड्यूल उसके अपने डिज़ाइन हैं और किसी और उत्पाद होने का दावा नहीं करते।","docs.disclaimer.p3":"यह एक सारांश है। Takelight पूरा अस्वीकरण अपने लाइसेंस अनुबंध के साथ दिखाता है।","docs.privacy.p1":"प्लगइन और स्टैंडअलोन ऐप कभी ऑनलाइन नहीं जाते: न खाता, न टेलीमेट्री, न नेटवर्क कोड, जिसे एक बिल्ड गेट अस्वीकार करता है। आपकी वोकल कभी आपके कंप्यूटर से बाहर नहीं जाती, और A/B के लिए लोड की गई रेफ़रेंस फ़ाइल सिर्फ़ मेमोरी में रहती है।","docs.privacy.p2":"संस्करण 1.0 से एक अलग सहायक अपडेट जाँचता है और आपका लाइसेंस सक्रिय करता है — सिर्फ़ तब, जब आप कहें। यह कभी कुछ डाउनलोड या इंस्टॉल नहीं करता।","docs.report.p1":"freallyproducts@gmail.com पर लिखें। जब Takelight ख़ुद विफल होता है, तो वह जो संदेश दिखाता है उसमें 'रिपोर्ट करें' होता है: यह आपके अपने ब्राउज़र में एक पेज खोलता है जो वह सब कुछ दिखाता है जो भेजा जाएगा, और जब तक आप 'भेजें' नहीं दबाते, कुछ भी आपके कंप्यूटर से बाहर नहीं जाता। क्रैश के बाद, अगली बार खोलने पर भी यही विकल्प मिलता है।","kit.skip":"सामग्री पर जाएँ","kit.nav.site":"साइट","kit.nav.home":"होम","kit.nav.features":"फ़ीचर्स","kit.nav.documentation":"दस्तावेज़ीकरण","kit.nav.changelog":"बदलाव लॉग","kit.nav.language":"भाषा","kit.nav.allApps":"सभी Freally ऐप्स","kit.badge.progress":"v0.5.6 पूरा · आगे v0.6.0","kit.cta.features":"सभी फ़ीचर्स देखें","kit.cta.docs":"दस्तावेज़ीकरण पढ़ें","kit.noDownloads":"अभी कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","kit.label.overview":"अवलोकन","kit.label.inside":"अंदर","kit.label.roadmap":"रोडमैप","kit.ladder.done":"पूरा","kit.ladder.planned":"नियोजित","kit.ladder.goal":"लक्ष्य","kit.ladder.later":"बाद में","kit.label.honesty":"ईमानदारी","kit.family.label":"Freally परिवार","kit.family.title":"<span class=\"hl-muted\">एक परिवार।</span> <span class=\"hl-bright\">दस ऐप्स।</span>","kit.cta.label":"क्या बदला","kit.cta.title":"<span class=\"hl-muted\">हर संस्करण,</span> <span class=\"hl-bright\">लिखित में।</span>","kit.cta.lede":"बदलाव लॉग में Freally Takelight में हुआ हर बदलाव, संस्करण-दर-संस्करण, सभी अठारह भाषाओं में दर्ज है।","kit.cta.changelog":"बदलाव लॉग पढ़ें","kit.footer.thisApp":"यह ऐप","kit.footer.family":"Freally परिवार","kit.status.devVersion":"विकास में · v0.5.6","kit.head.features":"<span class=\"hl-muted\">यह जो कुछ करता है,</span> <span class=\"hl-bright\">आमने-सामने।</span>","kit.label.numbers":"आँकड़ों में","kit.numbers.lead":"हर आँकड़ा ऐप से ही गिना गया है। कुछ भी अनुमानित नहीं है, और कुछ भी बढ़ाकर पूर्णांकित नहीं किया गया है।","kit.label.free":"आज मुफ़्त","kit.label.compare":"तुलना","kit.label.principles":"सिद्धांत","kit.label.limits":"सीमाएँ","kit.states.title":"स्थितियों का अर्थ","kit.states.done":"बना और टैग किया गया, पर इस साइट पर डाउनलोड नहीं","kit.states.planned":"अभी बनना बाकी है","kit.states.goal":"वह संस्करण जिस तक यह रास्ता जाता है","kit.states.later":"उसके बाद, और अभी तय नहीं","kit.states.ladder":"रास्ते का हर पड़ाव देखें","kit.head.documentation":"<span class=\"hl-muted\">यह कैसे काम करता है,</span> <span class=\"hl-bright\">क़दम-दर-क़दम।</span>","kit.search.placeholder":"दस्तावेज़ीकरण में खोजें","kit.docs.contents":"विषय-सूची","kit.head.changelog":"<span class=\"hl-muted\">हर बदलाव,</span> <span class=\"hl-bright\">संस्करण-दर-संस्करण।</span>","kit.changelog.lede":"सबसे नया पहले: Freally Takelight में जो कुछ बदला, इस साइट की हर भाषा में।","kit.changelog.versions":"संस्करण","kit.search.none":"इस साइट पर इससे कुछ भी मेल नहीं खाता।","kit.zoom.close":"बंद करें","changelog.1231a0c0224a":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.6</span><time class=\"release__date\" datetime=\"2026-10-27\">2026-10-27</time></span><span class=\"release__title\">विज़ुअल कार्ड</span>","changelog.ca7f81d415d0":"हर मॉड्यूल का कार्ड अब दिखाता है कि वह क्या करता है, सिर्फ़ उसके नॉब नहीं: EQ अपना कर्व आपकी वोकल के ऊपर बनाते हैं जब वह बज रही हो, कंप्रेसर दिखाते हैं कि आपकी वोकल कहाँ है और वे कितना दबाते हैं, और बाक़ी अपने रिपीट, अपना डिके, अपना स्टीरियो फ़ील्ड और अपना कर्व बनाते हैं। हर तस्वीर उसी गणित से निकाली जाती है जो साउंड बनाता है।","changelog.6b02e0d363a4":"जोड़ा गया","changelog.c885adad0ca5":"<strong>EQ कार्ड</strong> — पैरामेट्रिक, कंसोल और प्रोग्राम EQ अपना कर्व आपकी वोकल के एक लाइव स्पेक्ट्रम पर बनाते हैं, EQ से पहले (धुँधला) और उसके बाद (चमकीला), और पीक एक पल के लिए थमे रहते हैं। हर बैंड का कर्व पर एक बिंदु है: उसकी फ़्रीक्वेंसी और गेन को एक साथ हिलाने के लिए उसे ड्रैग करें, उसकी चौड़ाई के लिए उसके ऊपर माउस व्हील घुमाएँ, उसे वापस लाने के लिए उस पर डबल-क्लिक करें, या ऐरो कुंजियाँ इस्तेमाल करें। प्रोग्राम EQ के बिंदु उसकी फ़्रीक्वेंसी के बीच चलते हैं, जैसे उसके नॉब, और क्लास A में कंसोल EQ के बिंदु उन क़दमों पर बैठते हैं जो वह लेता है। डी-एसर वह बैंड दिखाता है जिसे वह सुनता है और वह कट जो वह लगाता है, और ट्रिम अपना हाई-पास।","changelog.e4155cb8a38e":"<strong>कंप्रेसर कार्ड</strong> — ऑप्टो, FET, VCA, वेरी-म्यू और पंच कंप्रेसर, वॉक्स लेवलर, लेवल राइडर और लिमिटर अपना कर्व बनाते हैं, इनपुट लेवल बनाम आउटपुट लेवल, उस जगह एक बिंदु के साथ जहाँ इस समय आपकी वोकल उस पर है और, नीचे, पिछले चार सेकंड का गेन रिडक्शन। थ्रेशोल्ड को कर्व के साथ ड्रैग करें, या ऐरो कुंजियाँ इस्तेमाल करें; यह उसे सेट करने वाला नॉब घुमाता है।","changelog.ec53ddb6a430":"<strong>गेट का कार्ड</strong> — उसका कर्व, और उसके नीचे पिछले चार सेकंड में उसे सुनाई देने वाला लेवल, उसके थ्रेशोल्ड के सापेक्ष, और जहाँ वह बंद है वहाँ छायांकित।","changelog.7c482c32b414":"<strong>स्पेस कार्ड</strong> — आपके प्रोजेक्ट की बीट और बार के सापेक्ष एक टाइमलाइन पर डिले के रिपीट, हर एक उतना ही ऊँचा जितना फ़ीडबैक और फ़िल्टर उसे छोड़ते हैं (पिंग-पोंग में बाएँ रेखा के ऊपर, दाएँ नीचे); रिवर्ब का डिके — प्री-डिले, शुरुआती रिफ़्लेक्शन और टेल; रिवर्स गेट का स्वेल; और डबलर, कोरस और चौड़ाई का स्टीरियो फ़ील्ड, ऊपर से देखा गया।","changelog.580a2bd46885":"<strong>कलर कार्ड</strong> — सैचुरेशन, एक्साइटर और लो-फ़ाई अपना कर्व बनाते हैं और, उसके पास, वे हार्मोनिक्स जो वह आपकी वोकल में अभी जोड़ता है।","changelog.2a6141e43be0":"बदला गया","changelog.4aa1a07ba478":"<strong>दो नॉब पर एक ड्रैग पूर्ववत करने में एक ही क़दम है</strong> — किसी EQ बैंड का बिंदु हिलाने से उसकी फ़्रीक्वेंसी और गेन एक साथ बदलते हैं, और एक पूर्ववत करें पूरा ड्रैग वापस ले लेता है, चाहे आपने उसे बीच में कितनी भी देर स्थिर रखा हो।","changelog.c64f3e0add84":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.5</span><time class=\"release__date\" datetime=\"2026-10-24\">2026-10-24</time></span><span class=\"release__title\">Input Check, ऐड-लिब और प्रीसेट</span>","changelog.f6741058398a":"रिकॉर्ड करने से पहले अपना लेवल सेट करें, किसी भी चेन के अपने संस्करण रखें, और कोई भी बदलाव एक कुंजी से वापस लें। ट्यून का Auto Key अब बीट से भी स्केल ढूँढ सकता है।","changelog.145f9c7721e2":"<strong>Input Check</strong> — रैक में Input Check दबाएँ और टेक को दस सेकंड तक गाएँ या बजाएँ; जब तक वह सुनता है, रिकॉर्डिंग लैंप एम्बर जलता है। फिर वह दिखाता है कि उसे क्या सुनाई दिया (पीक, लेवल, लाउडनेस, नॉइज़ फ़्लोर, रंबल, सिबिलेंस और प्लोसिव) और वह क्या सुझाता है: इनपुट नॉब, और चेन में पहले से मौजूद गेट, हाई-पास और डी-एसर। जब तक आप 'लागू करें' नहीं दबाते, कुछ नहीं बदलता, और जो मॉड्यूल चेन में नहीं है, वह यह बताता है — आपके लिए कुछ भी जोड़ा नहीं जाता। अगर टेक क्लिप होता है, तो वह आपसे अपने इंटरफ़ेस का गेन कम करने को कहता है।","changelog.807271b61fd0":"<strong>आपके प्रीसेट</strong> — 'प्रीसेट सहेजें…' चेन को वैसे ही रखता है जैसे आपने उसे गढ़ा है, आपके चुने नाम से, दस्तावेज़ › Freally Takelight › Presets में एक फ़ाइल के रूप में। 'मेरे प्रीसेट…' उन्हें लोड करता है, उनके नाम बदलता है, उन्हें एक्सपोर्ट करता है और मिटाता है, और किसी का भेजा प्रीसेट इंपोर्ट करता है (जो फ़ाइल प्रीसेट नहीं है, वह कारण के साथ अस्वीकार कर दी जाती है)। आपके प्रीसेट खोज में भी दिखते हैं, 'मेरे प्रीसेट' के नीचे, हर एक के साथ वह चेन जिससे वह बना था। जब वह चेन अपडेट होती है, तो आपका प्रीसेट उसके साथ चलता है और आपके बदलाव बनाए रखता है।","changelog.2110305b2ce9":"<strong>पूर्ववत करें और फिर से करें</strong> — साउंड में हर बदलाव, 100 क़दम तक: एक नॉब (हर ड्रैग एक क़दम), जोड़ा या हटाया गया मॉड्यूल, उसका कैरेक्टर, बायपास और सोलो, सेंड और फ़ेडर, चार बड़े नॉब, इनपुट नॉब, लोड की गई चेन या प्रीसेट, और Input Check का 'लागू करें'। ऊपर की पट्टी के तीर, या Ctrl+Z और Ctrl+Shift+Z (Ctrl+Y भी; Mac पर ⌘Z और ⌘⇧Z), जब तक विंडो पर फ़ोकस हो। दृश्य, थीम, भाषा और A/B रेफ़रेंस कभी पूर्ववत नहीं होते, और न ही आपके DAW का ऑटोमेशन; A और B के बीच बदलने पर उस पक्ष का इतिहास नए सिरे से शुरू होता है।","changelog.065bc3159eeb":"<strong>इनपुट नॉब</strong> — इन मीटर के पास, आने वाला लेवल, −24 से +24 dB तक। Input Check इसे सेट करता है, और आपका DAW इसे ऑटोमेट कर सकता है।","changelog.0c42df2ca995":"<strong>बीट से Auto Key</strong> — ट्यून एक साइडचेन इनपुट सुन सकता है: अपनी बीट Freally Takelight के साइडचेन पर भेजें और ट्यून के कार्ड पर <em>किसे सुनता है: साइडचेन</em> चुनें, और Auto Key आपकी आवाज़ के बजाय बीट के कॉर्ड के साथ चलता है। हर प्रोजेक्ट अपना चुनाव याद रखता है; सेटिंग्स नए प्रोजेक्ट के लिए इसे तय करती हैं। जब साइडचेन पर कुछ नहीं बजता, तो ट्यून आपकी वोकल सुनता है और यह बताता है।","changelog.057d5c78c13a":"<strong>खोलने और सहेजने के डायलॉग विंडो के ही हैं</strong> — वे Freally Takelight के सामने खुलते हैं और जब तक आप चुन न लें, उसे अपने पीछे रखते हैं।","changelog.adf9645e2b40":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-10-24\">2026-10-24</time></span><span class=\"release__title\">पहली रोशनी — Drake और चेन ब्राउज़र</span>","changelog.9befafdec87e":"पहला पूरा संस्करण: कोई कलाकार खोजें, एक दौर चुनें, प्ले दबाएँ, और पूरी वोकल चेन एक क्लिक में लोड हो जाती है। Drake के दौर और अठारह शैली चेन आ गईं, साथ में उन्हें आकार देने के लिए चार बड़े नॉब, तुलना के लिए एक रेफ़रेंस, और मिलाकर देखने के लिए आपकी चेन का दूसरा संस्करण।","changelog.abd39e3e1804":"<strong>चेन ब्राउज़र</strong> — खोज में कोई कलाकार या शैली लिखें (Ctrl+K, या Mac पर Cmd+K), और लिखते-लिखते चेन दौर और भूमिका के हिसाब से सज जाती हैं, उपनाम भी। फ़ील्ड ख़ाली हो, तो यह वे चेन सुझाता है जो आपने आख़िरी बार लोड की थीं; जो कलाकार अभी लाइब्रेरी में नहीं है, उसके लिए यह एक शैली चेन सुझाता है। हर क़दम कीबोर्ड से चलता है।","changelog.6372ffc30569":"<strong>Drake</strong> — तीन दौर: So Far Gone दौर (2009), Take Care दौर (2011) और आधुनिक दौर (2016–2026), हर एक के लिए एक लीड और आधुनिक दौर के लिए एक ऐड-लिब, और Take Care दौर की एक FX चेन जो सिर्फ़ रिटर्न पर चलती है।","changelog.8def9e786270":"<strong>अठारह शैली चेन</strong> — ट्रैप (2000 और 2010 के दशक), शिकागो ड्रिल, इमो रैप, क्लासिक R&amp;B, आधुनिक पॉप, रॉक, कंट्री पॉप और रेगेटन के लिए एक लीड और एक ऐड-लिब।","changelog.3370f1b4141c":"<strong>सरल मोड</strong> — रिकॉर्डिंग लैंप, चेन का नाम, चार बड़े नॉब और इन/आउट मीटर; उन्नत पूरा रैक दिखाता है। हर प्रोजेक्ट याद रखता है कि उसे किसमें छोड़ा गया था, और सेटिंग्स में आप चुनते हैं कि नया इंस्टेंस किसमें खुले।","changelog.b4ff7f2e9dce":"<strong>चार नॉब</strong> — ट्यून (वोकल कितनी तेज़ी से और कितने स्वाभाविक ढंग से ट्यून हो), टोन (गहरा या चमकीला, डी-एसर साथ चलता है), स्पेस (हर इफ़ेक्ट सेंड एक साथ) और मात्रा (आपकी ड्राई वोकल के मुक़ाबले पूरी चेन)। ट्यून, टोन और स्पेस बीच में हों और मात्रा पूरी, तो चेन वैसे ही बजती है जैसे वह बनाई गई थी, और हर चेन इसी तरह लोड होती है। आपका DAW चारों को ऑटोमेट कर सकता है।","changelog.8988c7fcad46":"<strong>A/B रेफ़रेंस</strong> — कोई तैयार गाना या वोकल खोलें (WAV, AIFF, FLAC या MP3, 20 मिनट तक), या उसे विंडो पर छोड़ें, और B उसे वहीं से चलाता है जहाँ आपका DAW है (स्टैंडअलोन में शुरुआत से), 20 ms के क्रॉसफ़ेड के साथ और आपकी वोकल की लाउडनेस से मिलाकर, ताकि आप लेवल नहीं, टोन परखें। यह सिर्फ़ मेमोरी में रहता है: कभी प्रोजेक्ट, किसी प्रीसेट या कहीं और सेव नहीं होता, और नेटवर्क ड्राइव पर रखी फ़ाइल अस्वीकार कर दी जाती है।","changelog.41af758b9239":"<strong>चेन की तुलना</strong> — आपकी चेन के दो संस्करण, A और B: B, A की कॉपी के रूप में शुरू होता है, हर एक अपने बदलाव रखता है, और एक क्लिक दोनों के बीच बदल देता है।","changelog.595ee8591a1b":"<strong>प्रोजेक्ट याद रखते हैं</strong> — चेन, दृश्य, सरल के नॉब और तुलना के दोनों पक्ष आपके प्रोजेक्ट के साथ सेव होते हैं। जो प्रोजेक्ट पढ़ा न जा सके, वह डिफ़ॉल्ट चेन पर खुलता है और एक बार यह बताता है।","changelog.4794b815283f":"<strong>Freally कर्सर</strong> — बीच में एक बिंदु वाला छल्ला, जो हर उस चीज़ के ऊपर बड़ा हो जाता है जिसे आप दबा सकते हैं।","changelog.3ad2505d4a1e":"<strong>टॉगल</strong> — हर टॉगल बंद होने पर ग्रे, पॉइंटर के नीचे सफ़ेद, और चालू होने पर Freally ग्रीन होता है, पॉइंटर उसके ऊपर हो या न हो।","changelog.d526eacf003a":"<strong>भरा रैक यह बताता है</strong> — एक रैक में उतने ही नॉब आ सकते हैं जितने Freally Takelight एक साथ हिला सकता है; उससे आगे का मॉड्यूल अस्वीकार हो जाता है, और एक संदेश बताता है कि रैक भरा हुआ है।","changelog.81c6aadde005":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-10-23\">2026-10-23</time></span><span class=\"release__title\">ट्यून</span>","changelog.ee8aa777588f":"पिच करेक्शन आ गया: ट्यून आपकी वोकल को उसके स्केल के सुरों पर खींचता है और उसके फ़ॉर्मेंट बनाए रखता है, स्केल ख़ुद ढूँढ लेता है, और रिकॉर्डिंग के दौरान कुछ मिलीसेकंड की लेटेंसी पर आ जाता है; और पिच शिफ़्टर किसी आवाज़ को दो ऑक्टेव तक ऊपर या नीचे ले जाता है।","changelog.e84a04d8e61c":"<strong>ट्यून</strong> — क्लासिक सिग्नल प्रोसेसिंग से पिच करेक्शन: 0 ms (वही सख़्त, सीढ़ीदार साउंड) से 400 ms तक की रीट्यून स्पीड, लंबे सुरों को साँस लेने देने के लिए ह्यूमनाइज़, और स्कूप व वाइब्रेटो बचाने के लिए फ़्लेक्स। आपकी आवाज़ अपना चरित्र बनाए रखती है, क्योंकि उसके फ़ॉर्मेंट अपनी जगह रहते हैं।","changelog.1b908b3463cd":"<strong>Auto Key</strong> — ट्यून आपकी वोकल सुनता है और लगभग चार सेकंड के गायन में उसका स्केल तय कर लेता है, तब तक क्रोमैटिक रहता है। सुनाई दे रहा स्केल एक क्लिक में लॉक करें, या 24 में से कोई भी स्केल चुनें, या क्रोमैटिक।","changelog.539fbc62230d":"<strong>पिच ग्राफ़</strong> — आपकी आवाज़ के आख़िरी चार सेकंड, गाई गई पिच और ट्यून की गई पिच, उस सुर के साथ जिसकी ओर वह खींची जाती है।","changelog.0f378cb53cb4":"<strong>Tracking</strong> — जब आपका DAW रिकॉर्ड करता है (या जब आप इसे चालू करते हैं), ट्यून कुछ मिलीसेकंड की लेटेंसी पर काम करता है ताकि आप चेन के ज़रिए गा सकें; मिक्स करते समय यह अपनी पूरी लेटेंसी बताता है ताकि आपका DAW वोकल को बीट के साथ समय पर रखे।","changelog.2e82019ea87e":"<strong>पिच शिफ़्टर</strong> — किसी आवाज़ को दो ऑक्टेव तक ऊपर या नीचे ले जाता है, उसके फ़ॉर्मेंट अलग से एक ऑक्टेव तक, मूल आवाज़ के साथ मिलाकर: एक ऑक्टेव नीचे का ऐड-लिब।","changelog.ba9e41780afd":"<strong>रिकॉर्डिंग लैंप सुनता है</strong> — जब तक Auto Key स्केल पहचानने के लिए सुन रहा होता है, यह एम्बर जलता है।","changelog.e86e8d397ace":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-23\">2026-10-23</time></span><span class=\"release__title\">स्पेस</span>","changelog.c223312c046d":"चार इफ़ेक्ट रिटर्न आ गए, आपके प्रोजेक्ट के साथ ताल में डिले, रिवर्ब, डबलिंग और चौड़ाई के साथ, हर रिटर्न पर एक थ्रो कुंजी, और इंसर्ट के लिए चार और मॉड्यूल।","changelog.eaa251798d7e":"<strong>चार इफ़ेक्ट रिटर्न</strong> — A से D, हर एक को इंसर्ट के अंत से उसके सेंड नॉब के ज़रिए फ़ीड मिलता है, अपने तीन स्लॉट और अपने फ़ेडर के साथ, और वोकल बस में जाते हुए वह ड्राई वोकल से मिलता है।","changelog.ebb30e23847f":"<strong>थ्रो</strong> — किसी रिटर्न की थ्रो कुंजी दबाए रखें और वोकल उसमें थ्रो हो जाती है, उसका सेंड 0 dB पर रहता है जब तक आप छोड़ न दें। थ्रो A से D होस्ट पैरामीटर भी हैं, इसलिए आपका DAW कोई थ्रो रिकॉर्ड करके उसे वापस चला सकता है।","changelog.39cab35a5560":"<strong>डिले</strong> — डिजिटल, टेप, एनालॉग, पिंग-पोंग और स्लैप, मिलीसेकंड में या आपके प्रोजेक्ट के साथ ताल में नोट वैल्यू के रूप में सेट, फ़ीडबैक में फ़िल्टर, वोकल के नीचे डकिंग, और चौड़ाई के साथ।","changelog.d45fe717d01c":"<strong>रिवर्ब</strong> — प्लेट, रूम, हॉल, चैंबर और एम्बिएंस, 0.1 से 20 सेकंड तक के डिके के साथ; और <strong>रिवर्स गेट</strong>, एक उभरता हुआ रिवर्स रिवर्ब जो कोई लेटेंसी नहीं जोड़ता।","changelog.4db2c68f321a":"<strong>डबलर, कोरस और चौड़ाई</strong> — एक टेक से दो से चार आवाज़ें, दो आवाज़ों वाला कोरस, और Haas डिले के साथ मोनो से 200 % तक की स्टीरियो चौड़ाई।","changelog.8be315d62f9e":"<strong>इंसर्ट के लिए चार और मॉड्यूल</strong> — छह टाइम कॉन्स्टेंट वाला वेरी-म्यू कंप्रेसर, लेवल राइडर, एक्साइटर और लो-फ़ाई।","changelog.2d718978085b":"<strong>आपके प्रोजेक्ट के साथ ताल में</strong> — नोट वैल्यू पर सेट किया गया डिले आपके DAW के टेम्पो के साथ चलता है, तब भी जब वह गाने के दौरान बदलता है।","changelog.e3c80cfe9d31":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span><span class=\"release__title\">Joint, पहले मॉड्यूल और डॉक्स साइट</span>","changelog.521a85ebded1":"रैक आ गया: पूरी वोकल चेन के लिए एक Joint, रेंडर किए गए हार्डवेयर पर Takelight के अपने डिज़ाइन के तेरह मॉड्यूल, और रिकॉर्डिंग लैंप।","changelog.657c896de46f":"<strong>Joint</strong> — सिग्नल के क्रम में एक रैक: दो स्लॉट का फ़्रंट एंड, बारह इंसर्ट और चार स्लॉट की वोकल बस, आपके DAW को उसकी लेटेंसी बताई जाती है, और मात्रा पूरी चेन को ड्राई वोकल के साथ मिलाती है।","changelog.44955680f91b":"<strong>बिना क्लिक के बदलाव</strong> — ट्रैक चलते-चलते मॉड्यूल जोड़ें, हटाएँ और बदलें: नया रैक ऑडियो से अलग तैयार होता है और 30 मिलीसेकंड के क्रॉसफ़ेड में आता है, नया कैरेक्टर क्रॉसफ़ेड होता है, और हर नॉब धीरे से सरकता है।","changelog.5883cafdd389":"<strong>तेरह मॉड्यूल</strong> — ट्रिम; पैरामेट्रिक, कंसोल और प्रोग्राम EQ; ऑप्टो, FET, VCA और पंच कंप्रेसर; वॉक्स लेवलर; डी-एसर; गेट; सैचुरेशन; और एक ट्रू-पीक लिमिटर।","changelog.da4d68a37948":"<strong>रैक स्क्रीन</strong> — हर मॉड्यूल रेंडर किए गए हार्डवेयर का एक कार्ड, उसके कैरेक्टर, बायपास, सोलो और गेन रिडक्शन के साथ, हर कंट्रोल कीबोर्ड की पहुँच में, 18 भाषाओं में।","changelog.19b404056636":"<strong>ऑटोमेशन</strong> — हर स्लॉट के 24 होस्ट पैरामीटर उसके मॉड्यूल के कंट्रोल क्रम से चलाते हैं, इसलिए पैरामीटर सूची कभी नहीं बदलती।","changelog.93ce19272231":"<strong>रिकॉर्डिंग लैंप और मीटर</strong> — बूथ का लैंप, Blender में डार्क और लाइट दोनों में रेंडर किया गया, तब हरा जलता है जब रैक में कोई मॉड्यूल हो और आपकी आवाज़ आ रही हो, और क्लिप होने पर लाल झपकता है; क्लिप लाइट वाले इन और आउट मीटर।","changelog.54bf2d68a5db":"<strong>रिपोर्ट करें</strong> — जब Takelight ख़ुद विफल हो, या क्रैश के बाद, आपके अपने ब्राउज़र में एक पेज वह सब कुछ दिखाता है जो रिपोर्ट भेजेगी, और जब तक आप 'भेजें' नहीं दबाते, कुछ नहीं भेजा जाता।","changelog.42b61e5ef13f":"<strong>डॉक्स साइट, पूरी</strong> — होम, फ़ीचर, मैनुअल, चेंजलॉग और संस्करण-सीढ़ी, 18 भाषाओं में।","changelog.2178abb38e7d":"<strong>लाइसेंस अनुबंध अब संस्करण 2 है</strong>, इसलिए Takelight आपसे इसे एक बार फिर स्वीकार करने को कहता है। यह और अस्वीकरण अब छोटे और ज़्यादा सरल हैं।","changelog.e6a2eb660b78":"<strong>एक सेटिंग कम</strong> — मानों के पास के रंगीन बिंदु हटा दिए गए हैं, और उनकी सेटिंग भी। क्रेडिट में अब सिर्फ़ लाइसेंस सूचनाएँ हैं।","changelog.5758b5c96327":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.1</span><time class=\"release__date\" datetime=\"2026-10-13\">2026-10-13</time></span><span class=\"release__title\">सेटिंग्स, नए रूप में</span>","changelog.898338328178":"<strong>सेटिंग्स, नए रूप में</strong> — ऊपरी पट्टी के गियर से खुलती हैं और × से बंद होती हैं; थीम चाँद और सूरज वाला डार्क/लाइट टॉगल है, हर छोटा विकल्प खिसकने वाले संकेतक वाला सेगमेंटेड कंट्रोल, और परिचय के लंबे पाठ पंक्तियों की सूची।","changelog.5c7b3a54f6e0":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-10-12\">2026-10-12</time></span><span class=\"release__title\">नींव, CI की रीढ़ और रिलीज़ का रास्ता</span>","changelog.e7f1a5798692":"एक ख़ाली Freally Takelight जो होस्ट में लोड होता है, ऑडियो को गुज़रने देता है, और एक भी फ़ीचर से पहले हर गेट, CI की दोनों शाखाएँ और रिलीज़ का रास्ता अपनी जगह रखता है।","changelog.82a7fc560af2":"<strong>प्लगइन, ख़ाली, हर फ़ॉर्मेट में</strong> — nih-plug से CLAP, उसी बाइनरी से clap-wrapper द्वारा प्रक्षेपित VST3 और AU, और एक स्टैंडअलोन ऐप। मोनो और स्टीरियो इनपुट, स्टीरियो आउटपुट; ऑडियो बिना बदले गुज़रती है।","changelog.9dc28fd94514":"<strong>पैरामीटर पूल</strong> — इनपुट, आउटपुट, मात्रा, बायपास, ट्रैकिंग, तीन मैक्रो, चार थ्रो और 24-24 सामान्य पैरामीटर वाले 30 स्लॉट, ताकि चेन लोड करने से होस्ट की पैरामीटर सूची कभी न बदले।","changelog.7a8b66c5fe5a":"<strong>एडिटर का ढाँचा</strong> — डार्क और लाइट में Freally UI किट, पहली बार चलाने पर EULA और अस्वीकरण, सेटिंग्स और परिचय, दाएँ से बाएँ लेआउट समेत 18 भाषाएँ।","changelog.ec039c3098d0":"<strong>गेट</strong> — न AI, न नेटवर्क, न उधार का कोड, उत्पाद के नाम और प्रतिबंधित शब्द, 1.0 से पहले कोई डाउनलोड नहीं, संस्करण-सीढ़ी, लाइसेंस, साझा crates, UI किट और हार्डवेयर आर्ट, भाषाएँ और लॉजिकल CSS, बाइंडिंग का भटकाव, और ऑडियो थ्रेड पर कोई मेमोरी आवंटन नहीं।","changelog.872b0df7744d":"<strong>ख़ुद होस्ट किया CI</strong> — <code>npm run ci:local</code> (Windows) और <code>npm run ci:linux</code> (Docker Desktop), गेटों की एक सूची; एडिटर और असली स्टैंडअलोन ऐप पर Playwright।","changelog.5cbd8ff53c0a":"<strong>रिलीज़ का रास्ता</strong> — <code>npm run release:local</code> ठीक उसी टैग को बिल्ड करता है, बंडलों को जाँचता है, चेकसम के साथ रिलीज़ फ़ोल्डर लिखता है, <code>target/</code> को उसी तक छाँटता है, और एक UAC प्रॉम्प्ट से VST3 और CLAP इंस्टॉल करता है।","changelog.4e9699d53d2d":"<strong>डॉक्स साइट का ढाँचा</strong> और चेन डेटा का ढाँचा (<code>tlc validate</code>, <code>tlc import-roster</code>)।"};
